device = cid_file.parent
try:
    is_emmc = (device / "type").read_text().strip() == "MMC"
except OSError:
    is_emmc = False
if is_emmc:
    sd_info = {
        'manufacturer': "Unknown", 'manufacturer_id': "Unknown",
        'oem_id': "Unknown", 'product_name': "Unknown",
        'product_revision': "Unknown", 'serial_number': "Unknown",
        'manufacturer_date': "Unknown", 'capacity': "Unknown",
        'total_bytes': 0
    }
    for key, attribute in (('product_name', 'name'),
                           ('manufacturer_date', 'date')):
        try:
            value = (device / attribute).read_text().strip()
            if value:
                sd_info[key] = value
        except OSError:
            pass
    for key, attribute, width in (('manufacturer_id', 'manfid', 2),
                                   ('oem_id', 'oemid', 4),
                                   ('serial_number', 'serial', 8)):
        try:
            value = int((device / attribute).read_text().strip(), 0)
            if value >= 0:
                sd_info[key] = f"{value:0{width}x}"
        except (OSError, ValueError):
            pass
    try:
        revision = int((device / "prv").read_text().strip(), 0)
        if 0 <= revision <= 255:
            sd_info['product_revision'] = f"{revision >> 4}.{revision & 15}"
    except (OSError, ValueError):
        pass
    try:
        # Linux block-device size is expressed in 512-byte sectors.
        sectors = int((device.parent / "size").read_text().strip())
        if sectors > 0:
            total_bytes = sectors * 512
            sd_info['total_bytes'] = total_bytes
            sd_info['capacity'] = f"{total_bytes / (1024.0**3):.1f} GiB"
    except (OSError, ValueError):
        pass
    return sd_info
